int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *asoc;
    int ret = -EINVAL;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EFAULT;

    if (asoc->ep->type != SOCK_STREAM || sk->sk_type != SOCK_STREAM)
        return -ESOCKTNOSUPPORT;

    if (!list_empty(&asoc->listen_queue) || !list_empty(&asoc->send_queue))
        return -EBUSY;

    ret = sock_create(kern_ptr->pf, SOCK_STREAM, IPPROTO_SCTP, sockp);
    if (ret < 0)
        return ret;

    sctp_association_dup_to_sock(asoc, (*sockp)->sk);
    sctp_assoc_migrate(sk, asoc, (*sockp)->sk);

    return 0;
}

int sctp_association_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *assoc;
    int ret = -EINVAL;

    assoc = sctp_id2assoc(sk, id);
    if (!assoc)
        return -EFAULT;

    if (!sockp || !*sockp)
        return -EINVAL;

    if (sctp_is_peeloff_disallowed(sk, assoc))
        return -EBUSY;

    ret = sock_create_kern(&init_net, sk->sk_family, SOCK_STREAM, PF_INET, sockp);
    if (ret < 0)
        return ret;

    ret = sctp_copy_sock(*sockp, sk, assoc);
    if (ret < 0) {
        sock_release(*sockp);
        return ret;
    }

    ret = sctp_migrate_association(*sockp, assoc);
    if (ret < 0) {
        sock_release(*sockp);
        return ret;
    }

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    struct sctp_association *asoc;
    int ret = -EINVAL;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EFAULT;

    if (sctp_wait_for_peeloff(sk, asoc)) {
        return -EBUSY;
    }

    ret = sock_create_kern(&init_net, sk->sk_family, SOCK_STREAM, IPPROTO_SCTP, sockp);
    if (ret < 0)
        return ret;

    sctp_copy_sock_props(sk, (*sockp)->sk);
    sctp_migrate_association(asoc, (*sockp)->sk);

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *assoc;
    int ret = -EINVAL;

    assoc = sctp_id2assoc(sk, id);
    if (!assoc)
        return -ESRCH;

    if (sk->sk_type != SOCK_STREAM || sk->sk_type != SOCK_SEQPACKET) {
        return -EINVAL;
    }

    if (!list_empty(&assoc->waiting_sk)) {
        return -EBUSY;
    }

    ret = sock_create_kern(current->nsproxy->net_ns, PF_INET, sk->sk_type,
                           sk->sk_protocol, sockp);
    if (ret < 0)
        return ret;

    sock_graft(*sockp, sk->sk_sleep);

    assoc->base.sk = (*sockp)->sk;

    return 0;
}
